213	func buildReleaseInput(doc map[string]any) (ReleasePlanInput, error) {
214		app, err := requiredString(doc, "app")
215		if err != nil {
216			return ReleasePlanInput{}, err
217		}
218		revision, err := requiredString(doc, "revision")
219		if err != nil {
220			return ReleasePlanInput{}, err
221		}
222		image, err := requiredString(doc, "image")
223		if err != nil {
224			return ReleasePlanInput{}, err
225		}
226		batchSize, err := positiveInt(doc, "batchSize")
227		if err != nil {
228			return ReleasePlanInput{}, err
229		}
230		spreadBy, err := optionalSpreadBy(doc)
231		if err != nil {
232			return ReleasePlanInput{}, err
233		}
234		clusters, err := parseClusters(doc["clusters"])
235		if err != nil {
236			return ReleasePlanInput{}, err
237		}
238		include, err := parseConditions(doc["include"], "include")
239		if err != nil {
240			return ReleasePlanInput{}, err
241		}
242		exclude, err := parseConditions(doc["exclude"], "exclude")
243		if err != nil {
244			return ReleasePlanInput{}, err
245		}
246	
247		return ReleasePlanInput{
248			App:       app,
249			Revision:  revision,
250			Image:     image,
251			BatchSize: batchSize,
252			Clusters:  clusters,
253			Include:   include,
254			Exclude:   exclude,
255			SpreadBy:  spreadBy,
256		}, nil
257	}
258	
259	// optionalSpreadBy reads the optional "spreadBy" field: absent or an empty
260	// string disables fault-domain spreading; a non-string value or a string of
261	// only whitespace is rejected. The tag key is used exactly as written.
262	func optionalSpreadBy(doc map[string]any) (string, error) {
263		v, ok := doc["spreadBy"]
264		if !ok {
265			return "", nil
266		}
267		s, ok := v.(string)
268		if !ok {
269			return "", fmt.Errorf("字段 %q 必须是字符串", "spreadBy")
270		}
271		if err := checkSpreadBy(s); err != nil {
272			return "", err
273		}
274		return s, nil
275	}
276	
277	// checkSpreadBy rejects a spreadBy value that is neither empty nor a usable
278	// tag key: a string of only whitespace can never match a valid tag key.
279	func checkSpreadBy(s string) error {
280		if s != "" && strings.TrimSpace(s) == "" {
281			return fmt.Errorf("字段 %q 不能只含空白", "spreadBy")
282		}
283		return nil
284	}
285	
286	// ValidateReleaseInput checks that a release configuration is well-formed:
287	// app/revision/image are non-empty, batchSize is a positive integer, spreadBy
288	// is empty or a usable tag key (not whitespace-only), cluster
289	// IDs are unique across every candidate (including disabled and filtered-out
290	// clusters), and tag/condition keys are non-empty. Errors name the field and
291	// the position in its list; within a cluster the ID is checked before its
292	// tags, and tag keys are examined in ascending order so repeated calls report
293	// the same error. The input is never mutated. MakeReleasePlan calls this
294	// automatically; library callers may use it to validate without planning.
295	func ValidateReleaseInput(in ReleasePlanInput) error {
296		if strings.TrimSpace(in.App) == "" {
297			return errors.New(`字段 "app" 不能为空或只含空白`)
298		}
299		if strings.TrimSpace(in.Revision) == "" {
300			return errors.New(`字段 "revision" 不能为空或只含空白`)
301		}
302		if strings.TrimSpace(in.Image) == "" {
303			return errors.New(`字段 "image" 不能为空或只含空白`)
304		}
305		if in.BatchSize <= 0 {
306			return errors.New(`字段 "batchSize" 必须是正整数`)
307		}
308		if err := checkSpreadBy(in.SpreadBy); err != nil {
309			return err
310		}
311		seen := make(map[string]struct{}, len(in.Clusters))
312		for i, c := range in.Clusters {
313			if strings.TrimSpace(c.ID) == "" {
314				return fmt.Errorf("clusters[%d]: 字段 %q 不能为空或只含空白", i, "id")
315			}
316			if _, dup := seen[c.ID]; dup {
317				return fmt.Errorf("clusters[%d]: 重复的集群标识 %q", i, c.ID)
318			}
319			seen[c.ID] = struct{}{}
320			if err := validateTagKeys(i, c.Tags); err != nil {
321				return err
322			}
323		}
324		if err := validateConditionKeys("include", in.Include); err != nil {
325			return err
326		}
327		if err := validateConditionKeys("exclude", in.Exclude); err != nil {
328			return err
329		}
330		return nil
331	}
332	
333	// validateTagKeys checks tag keys in ascending order for deterministic errors.
334	func validateTagKeys(clusterIndex int, tags map[string]string) error {
335		keys := make([]string, 0, len(tags))
336		for k := range tags {
337			keys = append(keys, k)
338		}
339		sort.Strings(keys)
340		for _, k := range keys {
341			if k == "" {
342				return fmt.Errorf("clusters[%d] 的标签键不能为空", clusterIndex)
343			}
344		}
345		return nil
346	}
347	
348	// validateConditionKeys checks that every condition is non-empty and has only
349	// non-empty keys; conditions are visited in original order and keys in
350	// ascending order for deterministic errors.
351	func validateConditionKeys(field string, conds []LabelCondition) error {
352		for i, cond := range conds {
353			if len(cond) == 0 {
354				return fmt.Errorf("%s[%d] 不能为空条件对象", field, i)
355			}
356			keys := make([]string, 0, len(cond))
357			for k := range cond {
358				keys = append(keys, k)
359			}
360			sort.Strings(keys)
361			for _, k := range keys {
362				if k == "" {
363					return fmt.Errorf("%s[%d] 的标签键不能为空", field, i)
364				}
365			}
366		}
367		return nil
368	}
369	
370	func requiredString(doc map[string]any, field string) (string, error) {
371		v, ok := doc[field]
372		if !ok {
373			return "", fmt.Errorf("缺少必需字段 %q", field)
374		}
375		s, ok := v.(string)
376		if !ok {
377			return "", fmt.Errorf("字段 %q 必须是字符串", field)
378		}
379		if strings.TrimSpace(s) == "" {
380			return "", fmt.Errorf("字段 %q 不能为空或只含空白", field)
381		}
382		return s, nil
383	}
384	
385	func positiveInt(doc map[string]any, field string) (int, error) {
386		v, ok := doc[field]
387		if !ok {
388			return 0, fmt.Errorf("缺少必需字段 %q", field)
389		}
390		n, ok := v.(json.Number)
391		if !ok {
392			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
393		}
394		i, err := n.Int64()
395		if err != nil || i <= 0 {
396			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
397		}
398		return int(i), nil
399	}
400	
401	func parseClusters(v any) ([]Cluster, error) {
402		if v == nil {
403			return nil, errors.New("缺少必需字段 \"clusters\"")
404		}
405		raw, ok := v.([]any)
406		if !ok {
407			return nil, errors.New("字段 \"clusters\" 必须是数组")
408		}
409		clusters := make([]Cluster, 0, len(raw))
410		seen := make(map[string]bool)
411		for i, item := range raw {
412			obj, ok := item.(map[string]any)
413			if !ok {
414				return nil, fmt.Errorf("clusters[%d] 必须是对象", i)
415			}
416			id, err := requiredString(obj, "id")
417			if err != nil {
418				return nil, fmt.Errorf("clusters[%d]: %w", i, err)
419			}
420			if seen[id] {
421				return nil, fmt.Errorf("clusters[%d]: 重复的集群标识 %q", i, id)
422			}
423			seen[id] = true
424	
425			disabled := false
426			if dv, present := obj["disabled"]; present {
427				b, ok := dv.(bool)
428				if !ok {
429					return nil, fmt.Errorf("集群 %q 的 \"disabled\" 必须是布尔值", id)
430				}
431				disabled = b
432			}
433	
434			tags := map[string]string{}
435			if tv, present := obj["tags"]; present {
436				tm, ok := tv.(map[string]any)
437				if !ok {
438					return nil, fmt.Errorf("集群 %q 的 \"tags\" 必须是对象", id)
439				}
440				keys := make([]string, 0, len(tm))
441				for k := range tm {
442					keys = append(keys, k)
443				}
444				sort.Strings(keys)
445				for _, k := range keys {
446					if k == "" {
447						return nil, fmt.Errorf("集群 %q 的标签键不能为空", id)
448					}
449					sv, ok := tm[k].(string)
450					if !ok {
451						return nil, fmt.Errorf("集群 %q 的标签 %q 值必须是字符串", id, k)
452					}
453					tags[k] = sv
454				}
455			}
456	
457			clusters = append(clusters, Cluster{ID: id, Disabled: disabled, Tags: tags})
458		}
459		return clusters, nil
460	}
461	
462	func parseConditions(v any, field string) ([]LabelCondition, error) {
463		if v == nil {
464			return []LabelCondition{}, nil
465		}
466		raw, ok := v.([]any)
467		if !ok {
468			return nil, fmt.Errorf("字段 %q 必须是条件数组", field)
469		}
470		conds := make([]LabelCondition, 0, len(raw))
471		for i, item := range raw {
472			obj, ok := item.(map[string]any)
473			if !ok {
474				return nil, fmt.Errorf("%s[%d] 必须是对象", field, i)
475			}
476			if len(obj) == 0 {
477				return nil, fmt.Errorf("%s[%d] 不能为空条件对象", field, i)
478			}
479			cond := LabelCondition{}
480			keys := make([]string, 0, len(obj))
481			for k := range obj {
482				keys = append(keys, k)
483			}
484			sort.Strings(keys)
485			for _, k := range keys {
486				if k == "" {
487					return nil, fmt.Errorf("%s[%d] 的标签键不能为空", field, i)
488				}
489				sv, ok := obj[k].(string)
490				if !ok {
491					return nil, fmt.Errorf("%s[%d] 的标签 %q 值必须是字符串", field, i, k)
492				}
493				cond[k] = sv
494			}
495			conds = append(conds, cond)
496		}
497		return conds, nil
498	}
499	
500	// MakeReleasePlan selects available clusters, orders them by ID, and splits
501	// them into batches. When SpreadBy names a tag, each batch holds at most one
502	// cluster per value of that tag (its fault domain) and every selected cluster
503	// must carry the tag. It validates the input first and never mutates it.
504	func MakeReleasePlan(in ReleasePlanInput) (ReleasePlan, error) {
505		if err := ValidateReleaseInput(in); err != nil {
506			return ReleasePlan{}, err
507		}
508		if len(in.Clusters) == 0 {
509			return ReleasePlan{}, errors.New("没有可发布的集群：未提供候选集群")
510		}
511	
512		selected := []string{}
513		excluded := []ExcludedCluster{}
514		for _, c := range in.Clusters {
515			switch {
516			case c.Disabled:
517				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonDisabled})
518			case matchesAny(c.Tags, in.Exclude):
519				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonExcludeMatched})
520			case len(in.Include) > 0 && !matchesAny(c.Tags, in.Include):
521				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonIncludeNotMatched})
522			default:
523				selected = append(selected, c.ID)
524			}
525		}
526	
527		sort.Strings(selected)
528		sort.Slice(excluded, func(i, j int) bool { return excluded[i].ID < excluded[j].ID })
529	
530		if len(selected) == 0 {
531			var b strings.Builder
532			b.WriteString("没有符合规则的可用集群，各候选集群未入选原因：")
533			for _, e := range excluded {
534				b.WriteString("\n  ")
535				b.WriteString(e.ID)
536				b.WriteString("：")
537				b.WriteString(e.Reason)
538			}
539			return ReleasePlan{}, errors.New(b.String())
540		}
541	
542		var batches []Batch
543		if in.SpreadBy == "" {
544			batches = chunkBatches(selected, in.BatchSize)
545		} else {
546			domains, err := faultDomains(in.Clusters, selected, in.SpreadBy)
547			if err != nil {
548				return ReleasePlan{}, err
549			}
550			batches = spreadBatches(selected, domains, in.BatchSize)
551		}
552	
553		return ReleasePlan{
554			App:      AppInfo{Name: in.App, Revision: in.Revision, Image: in.Image},
555			Batches:  batches,
556			Excluded: excluded,
557		}, nil
558	}
559	
560	// chunkBatches splits the ascending IDs into batches of at most batchSize.
561	func chunkBatches(selected []string, batchSize int) []Batch {
562		batches := []Batch{}
563		for i := 0; i < len(selected); i += batchSize {
564			end := i + batchSize
565			if end > len(selected) {
566				end = len(selected)
567			}
568			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: selected[i:end]})
569		}
570		return batches
571	}
572	
573	// faultDomains maps every selected cluster ID to the exact value of its
574	// spreadBy tag. A selected cluster missing the tag fails the whole plan;
575	// selected is ascending, so the smallest such ID is reported. An empty
576	// string tag value is a valid fault domain, distinct from a missing tag.
577	func faultDomains(clusters []Cluster, selected []string, spreadBy string) (map[string]string, error) {
578		tagsByID := make(map[string]map[string]string, len(clusters))
579		for _, c := range clusters {
580			tagsByID[c.ID] = c.Tags
581		}
582		domains := make(map[string]string, len(selected))
583		for _, id := range selected {
584			v, ok := tagsByID[id][spreadBy]
585			if !ok {
586				return nil, fmt.Errorf("集群 %q 缺少故障域标签 %q", id, spreadBy)
587			}
588			domains[id] = v
589		}
590		return domains, nil
591	}
592	
593	// spreadBatches packs the ascending IDs into batches of at most batchSize
594	// with at most one cluster per fault domain in each batch. Each batch takes
595	// the smallest still-unscheduled IDs whose domains do not conflict with the
596	// batch; conflicting clusters are deferred to later batches, so a batch may
597	// be short only when no non-conflicting cluster remains. Every ID appears in
598	// exactly one batch and IDs stay ascending within a batch.
599	func spreadBatches(selected []string, domains map[string]string, batchSize int) []Batch {
600		remaining := append([]string(nil), selected...)
601		batches := []Batch{}
602		for len(remaining) > 0 {
603			used := make(map[string]struct{}, batchSize)
604			batch := []string{}
605			deferred := []string{}
606			for _, id := range remaining {
607				d := domains[id]
608				if _, conflict := used[d]; len(batch) < batchSize && !conflict {
609					used[d] = struct{}{}
610					batch = append(batch, id)
611				} else {
612					deferred = append(deferred, id)
613				}
614			}
615			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: batch})
616			remaining = deferred
617		}
618		return batches
619	}
620	
621	func matchesAny(tags map[string]string, conditions []LabelCondition) bool {
622		for _, cond := range conditions {
623			if matchesAll(tags, cond) {
624				return true
625			}
626		}
627		return false
628	}
629	
630	func matchesAll(tags map[string]string, cond LabelCondition) bool {
631		for k, v := range cond {
632			tv, ok := tags[k]
633			if !ok || tv != v {
634				return false
635			}
636		}
637		return true
638	}
639

